import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring } from '../remotionShim';
{/* Start Google Fonts Loader */}
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */}



export type MRRChurnAnimationProps = Record<string, any>;

const MRRChurnAnimation: React.FC<MRRChurnAnimationProps> = ({
  backgroundColor = "#f4f8d3",
  transparentBackground = false,
  durationInSeconds = 10,
  bucketColor = "#e62657",
  waterColor = "#29b6f6",
  textColor = "#3e4a31",
  topLabel = "New members",
  middleLabel = "MRR",
  bottomLabel = "Churned members",
}) => {

  useFontLoader(["Inter"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Layout calculations
  const cx = width * 0.35;
  const cy = height * 0.45;
  const textX = cx + 350;

  // --- Animations ---

  // 1. Main Stream flows down
  const streamSpring = spring({ frame, fps, delay: 20, config: { damping: 15 } });
  const rawStreamHeight = interpolate(streamSpring, [0, 1], [0, 350]);
  const streamHeight = Math.max(0, rawStreamHeight);
  
  // Splash appears as stream hits bottom
  const splashOpacity = interpolate(streamSpring, [0.8, 1], [0, 1], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' });

  // 2. Bucket Drop & Bounce
  const bucketScaleSpring = spring({ frame, fps, delay: 35, config: { mass: 1.2, damping: 12, stiffness: 120 } });
  const bucketScale = Math.max(0, bucketScaleSpring);

  // 3. Leaks shoot out
  const leakProgress = spring({ frame, fps, delay: 55, config: { damping: 15 } });
  const leakRadius = Math.max(0, interpolate(leakProgress, [0, 1], [0, 250]));

  // 4. Puddle grows
  const puddleSpring = spring({ frame, fps, delay: 65, config: { damping: 14 } });
  const puddleBreath = 1 + Math.sin(frame / 15) * 0.015;
  const finalPuddleScale = Math.max(0, puddleSpring) * puddleBreath;

  // 5. Text Fades
  const topTextOpacity = interpolate(frame, [25, 40], [0, 1], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' });
  const topTextY = interpolate(frame, [25, 40], [20, 0], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' });

  const midTextOpacity = interpolate(frame, [50, 65], [0, 1], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' });
  const midTextY = interpolate(frame, [50, 65], [20, 0], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' });

  const botTextOpacity = interpolate(frame, [80, 95], [0, 1], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' });
  const botTextY = interpolate(frame, [80, 95], [20, 0], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' });

  // Text Styling
  const baseTextStyle: React.CSSProperties = {
    position: 'absolute',
    left: textX,
    fontSize: '64px',
    fontWeight: 600,
    color: textColor,
    fontFamily: 'Inter, sans-serif',
    whiteSpace: 'nowrap',
    transition: 'none',
  };

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, transition: "none", overflow: 'hidden' }}>
      
      {/* --- LAYER 1: Puddle (Bottom-most) --- */}
      <div style={{ position: 'absolute', left: cx, top: cy + 240, width: 0, height: 0, transform: `scale(${finalPuddleScale})`, transition: 'none' }}>
        <svg style={{ overflow: 'visible', position: 'absolute' }}>
          <g transform="translate(0, 0)">
            <ellipse cx="0" cy="15" rx="160" ry="40" fill={waterColor} />
            <ellipse cx="-100" cy="20" rx="80" ry="25" fill={waterColor} />
            <ellipse cx="110" cy="25" rx="90" ry="30" fill={waterColor} />
            <ellipse cx="-40" cy="30" rx="100" ry="20" fill={waterColor} />
            <ellipse cx="60" cy="25" rx="110" ry="25" fill={waterColor} />
            {/* Sparkles */}
            <g transform="translate(120, 50) scale(0.8)">
              <path d="M 0,-10 Q 0,0 10,0 Q 0,0 0,10 Q 0,0 -10,0 Q 0,0 0,-10 Z" fill="#ffffff" opacity={0.6} />
            </g>
            <g transform="translate(-100, 60) scale(0.5)">
              <path d="M 0,-10 Q 0,0 10,0 Q 0,0 0,10 Q 0,0 -10,0 Q 0,0 0,-10 Z" fill="#ffffff" opacity={0.6} />
            </g>
          </g>
        </svg>
      </div>

      {/* --- LAYER 2: Bucket Inner Back --- */}
      <div style={{ position: 'absolute', left: cx, top: cy, width: 0, height: 0, transform: `scale(${bucketScale})`, transformOrigin: '0px 220px', transition: 'none' }}>
        <svg style={{ overflow: 'visible', position: 'absolute' }}>
          <ellipse cx="0" cy="0" rx="100" ry="35" fill="#a01545" />
        </svg>
      </div>

      {/* --- LAYER 3: Main Stream --- */}
      <div style={{ position: 'absolute', left: cx, top: cy - 350, width: 0, height: 0, transition: 'none' }}>
        <svg style={{ overflow: 'visible', position: 'absolute' }}>
          <polygon points={`-15,0 15,0 12,${streamHeight} -12,${streamHeight}`} fill={waterColor} />
          {streamHeight > 0 && (
            <g style={{ clipPath: `url(#stream-clip)` }}>
               <clipPath id="stream-clip">
                  <polygon points={`-15,0 15,0 12,${streamHeight} -12,${streamHeight}`} />
               </clipPath>
               {/* Animated highlight lines for flow effect */}
               <path d="M -5,0 L -5,1000" stroke="#ffffff" strokeWidth="4" opacity={0.4} strokeDasharray="20 40" strokeDashoffset={-frame * 15} />
               <path d="M 5,0 L 5,1000" stroke="#ffffff" strokeWidth="2" opacity={0.3} strokeDasharray="15 30" strokeDashoffset={-frame * 12 + 10} />
            </g>
          )}
        </svg>
      </div>

      {/* --- LAYER 4: Bucket Front Body --- */}
      <div style={{ position: 'absolute', left: cx, top: cy, width: 0, height: 0, transform: `scale(${bucketScale})`, transformOrigin: '0px 220px', transition: 'none' }}>
        <svg style={{ overflow: 'visible', position: 'absolute' }}>
          {/* Main Body */}
          <path d="M -100,0 L -75,220 A 75,25 0 0,0 75,220 L 100,0 A 100,35 0 0,1 -100,0 Z" fill={bucketColor} />
          
          {/* Handle Knobs */}
          <circle cx="-98" cy="10" r="7" fill="#d4c017" />
          <circle cx="98" cy="10" r="7" fill="#d4c017" />
          
          {/* Handle Loop */}
          <path d="M -102,15 C -140,110 140,110 102,15" fill="none" stroke="#ffeb3b" strokeWidth="10" strokeLinecap="round" />
          
          {/* Holes */}
          <ellipse cx="-45" cy="160" rx="6" ry="12" fill="#5e0620" transform="rotate(15, -45, 160)" />
          <ellipse cx="45" cy="160" rx="6" ry="12" fill="#5e0620" transform="rotate(-15, 45, 160)" />
          
          {/* Splash particles at top of bucket */}
          {splashOpacity > 0 && (
             <g opacity={splashOpacity}>
                <circle cx="-20" cy="-15" r="5" fill={waterColor} transform={`translate(0, ${Math.sin(frame/2)*8})`} />
                <circle cx="25" cy="-5" r="4" fill={waterColor} transform={`translate(0, ${Math.cos(frame/2.5)*10})`} />
                <circle cx="5" cy="5" r="3" fill="#ffffff" opacity={0.6} transform={`translate(0, ${Math.sin(frame/3)*6})`} />
             </g>
          )}
        </svg>
      </div>

      {/* --- LAYER 5: Leaks --- */}
      <div style={{ position: 'absolute', left: cx, top: cy, width: 0, height: 0, transform: `scale(${bucketScale})`, transformOrigin: '0px 220px', transition: 'none' }}>
        <svg style={{ overflow: 'visible', position: 'absolute' }}>
          {/* Left Leak */}
          <clipPath id="leak-mask-left">
            <circle cx="-45" cy="160" r={leakRadius} />
          </clipPath>
          <g clipPath="url(#leak-mask-left)">
            <path d="M -45,160 Q -90,180 -120,270" fill="none" stroke={waterColor} strokeWidth="12" strokeLinecap="round" />
            <path d="M -45,160 Q -90,180 -120,270" fill="none" stroke="#ffffff" strokeWidth="4" opacity={0.5} strokeDasharray="15 30" strokeDashoffset={-frame * 10} />
          </g>

          {/* Right Leak */}
          <clipPath id="leak-mask-right">
            <circle cx="45" cy="160" r={leakRadius} />
          </clipPath>
          <g clipPath="url(#leak-mask-right)">
            <path d="M 45,160 Q 90,180 120,270" fill="none" stroke={waterColor} strokeWidth="12" strokeLinecap="round" />
            <path d="M 45,160 Q 90,180 120,270" fill="none" stroke="#ffffff" strokeWidth="4" opacity={0.5} strokeDasharray="15 30" strokeDashoffset={-frame * 10} />
          </g>
        </svg>
      </div>

      {/* --- LAYER 6: Text Elements --- */}
      <div style={{ ...baseTextStyle, top: cy - 250, opacity: topTextOpacity, transform: `translateY(${topTextY}px)` }}>
        {topLabel}
      </div>

      <div style={{ ...baseTextStyle, top: cy + 60, opacity: midTextOpacity, transform: `translateY(${midTextY}px)` }}>
        {middleLabel}
      </div>

      <div style={{ ...baseTextStyle, top: cy + 260, opacity: botTextOpacity, transform: `translateY(${botTextY}px)` }}>
        {bottomLabel}
      </div>

    </AbsoluteFill>
  );
};

export default MRRChurnAnimation;